let mut a = Asset::new("RAY / Chromatic Cell Conveyor");
let text = a.text_control("text", "Letters (Unicode characters)", "RAY");
let speed = a.scalar("speed", "Conveyor speed", 0.5, "letters/s");
let spacing = a.scalar("spacing", "Cell spacing", 24., "px");
let radius = a.scalar("radius", "Cell radius", 13., "px");
let size = a.scalar("size", "Letter size", 460., "px");
let pink = a.color("pink", "Candy pink", [1.,0.09,0.48,1.]);
let green = a.color("green", "Acid mint", [0.12,0.9,0.18,1.]);
let blue = a.color("blue", "Electric blue", [0.04,0.3,1.,1.]);
let bg = a.rectangle("background",500.,888.);
let bg = a.fill("night",&bg,[0.002,0.004,0.009,1.]);
let mut out = bg;
let c = a.circle("cell",radius.clone());
let c = a.fill("cell_base",&c,[0.8,0.8,0.8,1.]);
let shadow = a.circle("shadow",radius.clone());
let shadow = a.fill("shadow_fill",&shadow,[0.18,0.18,0.18,1.]);
let shadow = a.translate("shadow_shift",&shadow,[3.,4.]);
let cell = a.merge("cell_depth",&shadow,&c);
let shine = a.circle("shine",radius.clone()*0.34);
let shine = a.fill("shine_fill",&shine,[1.,1.,1.,0.65]);
let shine = a.translate("shine_shift",&shine,vec2(radius.clone()*-0.32,radius.clone()*-0.32));
let cell = a.merge("cell_finish",&cell,&shine);
let dot = a.circle("dot",2.2);
let dots = a.grid("dust_grid",21.,38.,[25.,24.],[0.,0.]);
let dots = a.copies("dust_copies",&dot,&dots);
let dots = a.wrangle("dust_palette",&dots,"Instances","let n = (index * 17 + 3) % 5; color = if n==0 {chc(\"pink\")} else if n==1 {chc(\"green\")} else if n==2 {chc(\"blue\")} else {[0.65,0.7,0.8,1.]}; opacity=0.2 + 0.45*(time.seconds*1.0471975512 + index as f64*0.23).sin().abs();",&[("pink",pink.clone()),("green",green.clone()),("blue",blue.clone())]);
out = a.merge("dust_over_night",&out,&dots);
for i in 0..3 {
 let select = a.add(Node::new(&key("select",i),"fold.motion.text_select").value("text",text.clone()).value("characters",true).value("index",i as f64)).socket("value");
 let letter = a.add(Node::new(&key("letter",i),"fold.motion.text").link("text",&select).value("size",size.clone()));
 let letter = a.align(&key("letter_center",i),&letter,[0.,0.]);
 let points = a.shape_points(&key("letter_cells",i),&letter,spacing.clone());
 let copies = a.copies(&key("letter_copies",i),&cell,&points);
 let copies = a.wrangle(&key("letter_palette",i),&copies,"Instances","let n = (index*13 + (position[0]/24.).abs() as usize) % 5; color = if n==0 {chc(\"pink\")} else if n==1 {chc(\"green\")} else if n==2 {chc(\"blue\")} else if n==3 {[1.,1.,1.,1.]} else {[0.4,0.43,0.48,1.]};",&[("pink",pink.clone()),("green",green.clone()),("blue",blue.clone())]);
 let phase = (time()*speed.clone() + i as f64).modulo(3.);
 let y = (phase - 1.) * -620. + 444.;
 let copies = a.translate(&key("conveyor",i),&copies,vec2(250.,y));
 out = a.merge(&key("stack",i),&out,&copies);
}
a.output(&out);
a

